{
  "name": "agent-proxy-kit",
  "version": "0.1.0",
  "description": "Normalize long-running agent and LLM streams into honest progress events.",
  "type": "module",
  "license": "MIT",
  "author": "swyx <swyx@swyx.io>",
  "homepage": "https://github.com/swyxio/agent-proxy-kit#readme",
