    "type": "git",
    "url": "git+https://github.com/swyxio/agent-proxy-kit.git"
  },
  "bugs": {
    "url": "https://github.com/swyxio/agent-proxy-kit/issues"
  },
  "keywords": [
    "llm",
    "progress",
    "streaming",
    "sse",
    "openai",
    "xai",
    "gemini",
    "featherless",
    "ux"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
